ALTER TABLE scheduled_job_runs MODIFY started_at timestamp(6) NULL, MODIFY finished_at timestamp(6) NULL, ADD COLUMN lease_owner varchar(128) NOT NULL DEFAULT '', ADD COLUMN lease_until timestamp(6) NULL, ADD COLUMN dispatched_at timestamp(6) NULL, ADD COLUMN payload text NOT NULL DEFAULT ('{}'), ADD COLUMN timeout_seconds bigint NOT NULL DEFAULT 30, ADD COLUMN lock_ttl_seconds bigint NOT NULL DEFAULT 60, ADD KEY scheduled_job_runs_queued_idx(trigger_source,status,dispatched_at,created_at,id), ADD KEY scheduled_job_runs_running_idx(trigger_source,status,lease_until,id), ADD KEY scheduled_job_runs_created_idx(scheduled_job_id,created_at,id);
